/**
 * scripts/make_corpus.js
 *
 * Produces verification corpus for Rogue 2048:
 * (a) At least 30 REAL UI runs with real touch swipes and taps under DEFAULT cadence
 *     (no ?first/?draft/?stones overrides, no debug injection), played by a driver with
 *     a corner/greedy policy until game over, including Rewind chains, Diagonal, Eraser,
 *     Mason, and Last Stand.
 * (b) At least 5 long runs (>= 1500 moves) generated by driving GameController in Node
 *     with sim bots and all relics, serialized in the exact same runLog shape and event format.
 * (c) At least 3 long (>= 1000 moves) runs generated under CANONICAL_CONFIG (default hazard
 *     schedule, default draft pool, no forced relics, no stoneLifetime) using sim bots with abilities.
 *
 * Saves corpus to scripts/out/corpus/ (gitignored) and writes 3 small fixtures:
 *   - verify/fixtures/fixture_rewind.json
 *   - verify/fixtures/fixture_mason.json
 *   - verify/fixtures/fixture_last_stand.json
 *
 * Outputs:
 *   - scripts/out/verify_corpus.txt
 *   - scripts/out/performance.txt
 */

import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';

import { findChrome } from './find_chrome.js';
import { GameController } from '../game/controller.js';
import { createBot, createExpectimaxBot, chooseStoneCell } from '../sim/bots.js';
import { RELIC_IDS } from '../sim/relics.js';
import { verifyRun } from '../verify/verify_run.js';
import { computeRulesVersion, computeReplayVersion } from '../verify/version.js';
import { DEFAULT_UI_CONFIG_OVERRIDES, dailySeed } from '../verify/profile.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, '..');
const distDir = path.join(rootDir, 'dist');
const corpusDir = path.join(rootDir, 'scripts', 'out', 'corpus');
const fixturesDir = path.join(rootDir, 'verify', 'fixtures');
const outDir = path.join(rootDir, 'scripts', 'out');

function sleep(ms) {
  return new Promise(r => setTimeout(r, ms));
}

function startStaticServer() {
  const MIME_TYPES = {
    '.html': 'text/html; charset=utf-8',
    '.js': 'text/javascript; charset=utf-8',
    '.css': 'text/css; charset=utf-8',
    '.json': 'application/json; charset=utf-8',
    '.svg': 'image/svg+xml',
    '.png': 'image/png',
    '.woff2': 'font/woff2',
  };

  const server = http.createServer((req, res) => {
    const parsedUrl = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    let pathname = decodeURIComponent(parsedUrl.pathname);
    let relPath = pathname.replace(/^\/+/, '');
    let filePath = path.join(distDir, relPath === '' ? 'index.html' : relPath);

    if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Not Found');
      return;
    }

    const ext = path.extname(filePath).toLowerCase();
    const contentType = MIME_TYPES[ext] || 'application/octet-stream';
    res.writeHead(200, { 'Content-Type': contentType });
    fs.createReadStream(filePath).pipe(res);
  });

  return new Promise((resolve, reject) => {
    server.listen(0, '127.0.0.1', () => {
      resolve(server);
    });
    server.on('error', reject);
  });
}

function getFreePort() {
  return new Promise((resolve, reject) => {
    const srv = http.createServer();
    srv.listen(0, '127.0.0.1', () => {
      const port = srv.address().port;
      srv.close(() => resolve(port));
    });
    srv.on('error', reject);
  });
}

async function getWsUrl(port) {
  for (let attempt = 0; attempt < 50; attempt++) {
    try {
      const res = await fetch(`http://127.0.0.1:${port}/json`);
      if (res.ok) {
        const list = await res.json();
        const page = list.find(t => t.type === 'page');
        if (page && page.webSocketDebuggerUrl) {
          return page.webSocketDebuggerUrl;
        }
      }
    } catch {}
    await sleep(100);
  }
  throw new Error(`Failed to connect to Chrome remote debugging on port ${port}`);
}

class CdpClient {
  constructor(wsUrl) {
    this.wsUrl = wsUrl;
    this.id = 0;
    this.callbacks = new Map();
    this.ready = this.init();
  }

  init() {
    return new Promise((resolve, reject) => {
      const WS = globalThis.WebSocket;
      this.ws = new WS(this.wsUrl);
      this.ws.onopen = () => resolve();
      this.ws.onerror = (err) => reject(err);
      this.ws.onmessage = (event) => {
        const msg = JSON.parse(event.data);
        if (msg.id && this.callbacks.has(msg.id)) {
          const { res, rej } = this.callbacks.get(msg.id);
          this.callbacks.delete(msg.id);
          if (msg.error) rej(new Error(msg.error.message));
          else res(msg.result);
        }
      };
    });
  }

  send(method, params = {}) {
    return new Promise((res, rej) => {
      const id = ++this.id;
      this.callbacks.set(id, { res, rej });
      this.ws.send(JSON.stringify({ id, method, params }));
    });
  }

  async eval(expr) {
    const r = await this.send('Runtime.evaluate', {
      expression: expr,
      returnByValue: true,
      awaitPromise: true,
    });
    if (r.exceptionDetails) {
      throw new Error(`Eval exception: ${r.exceptionDetails.text || JSON.stringify(r.exceptionDetails)}`);
    }
    return r.result.value;
  }

  close() {
    try { this.ws.close(); } catch {}
  }
}

/**
 * Plays a single real UI run in headless Chrome under DEFAULT cadence.
 */
async function playRealUiRun(cdp, baseUrl, runIndex, targetRelicFocus = null) {
  // Navigate to fresh root without query overrides
  await cdp.send('Page.navigate', { url: baseUrl });
  await sleep(250);

  // Click START
  await cdp.eval(`
    (() => {
      const btn = document.getElementById('btn-play-start');
      if (btn) btn.click();
    })()
  `);
  await sleep(100);

  let rewindChainExecuted = false;
  let diagonalUsed = false;
  let eraserUsed = false;
  let masonUsed = false;
  let moves = 0;
  const maxMoves = 1500;

  while (moves < maxMoves) {
    const isGameOver = await cdp.eval(`Boolean(window.controller && window.controller.isGameOver())`);
    if (isGameOver) {
      break;
    }

    // Step execution within browser
    const stepAction = await cdp.eval(`
      (async () => {
        const ctrl = window.controller;
        if (!ctrl) return { action: 'wait' };

        // 1. Pending decisions
        if (ctrl.hasPendingDecision()) {
          const dec = ctrl.getPendingDecision();
          if (dec.type === 'draft') {
            const draftOverlay = document.getElementById('draft-overlay');
            if (!draftOverlay || draftOverlay.classList.contains('hidden')) {
              return { action: 'wait_draft_modal' };
            }
            const offers = dec.offers || [];
            const priority = ['rewind', 'diagonal_charge', 'eraser', 'mason', 'last_stand'];
            if ('${targetRelicFocus}') {
              priority.unshift('${targetRelicFocus}');
            }
            let choice = offers[0];
            let choiceIdx = 0;
            for (const p of priority) {
              const idx = offers.indexOf(p);
              if (idx !== -1) {
                choice = p;
                choiceIdx = idx;
                break;
              }
            }
            const row = document.getElementById('draft-offers-row');
            const cards = row ? Array.from(row.querySelectorAll('.draft-card, .draftcard')) : [];
            if (cards.length > choiceIdx && cards[choiceIdx]) {
              cards[choiceIdx].click();
            } else if (cards.length > 0) {
              cards[0].click();
            }
            return { action: 'draft', choice };
          } else if (dec.type === 'mason') {
            const board = document.getElementById('game-board');
            if (!board || !board.classList.contains('draftdim')) {
              return { action: 'wait_mason_modal' };
            }
            const chosen = dec.candidates[0];
            const cell = document.querySelector('.cell[data-index=\"' + chosen + '\"], .grid-cell[data-index=\"' + chosen + '\"]');
            if (cell) cell.click();
            return { action: 'mason', chosen };
          }
        }

        // 2. Ability triggering
        const abState = ctrl.getAbilityState();
        const rwLevels = ctrl.getRewindUndoLevels ? ctrl.getRewindUndoLevels() : 0;
        if (!${rewindChainExecuted} && rwLevels >= 2 && ctrl.state.moveCount >= 8) {
          const rwBtn = document.querySelector('button.ability-btn[data-relic=\"rewind\"]');
          if (rwBtn && !rwBtn.disabled) {
            rwBtn.click();
            return { action: 'rewind_chain_1' };
          }
        }

        // Diagonal ability
        if (!${diagonalUsed} && abState.diagonal_charge && abState.diagonal_charge.charges > 0) {
          const targets = ctrl.getLegalTargets('diagonal_charge');
          if (targets && targets.length > 0) {
            const t = targets[0];
            const btn = document.querySelector('button.ability-btn[data-relic=\"diagonal_charge\"]');
            if (btn && !btn.disabled) {
              btn.click();
              const fromCell = document.querySelector('.cell[data-index=\"' + t.from + '\"], .tile[data-index=\"' + t.from + '\"]');
              const toCell = document.querySelector('.cell[data-index=\"' + t.to + '\"], .tile[data-index=\"' + t.to + '\"]');
              if (fromCell) fromCell.click();
              if (toCell) toCell.click();
              return { action: 'diagonal', target: t };
            }
          }
        }

        // Eraser ability
        if (!${eraserUsed} && abState.eraser && abState.eraser.charges > 0) {
          const targets = ctrl.getLegalTargets('eraser');
          if (targets && targets.length > 0) {
            const t = targets[0];
            const btn = document.querySelector('button.ability-btn[data-relic=\"eraser\"]');
            if (btn && !btn.disabled) {
              btn.click();
              const cell = document.querySelector('.cell[data-index=\"' + t.cell + '\"], .tile[data-index=\"' + t.cell + '\"]');
              if (cell) cell.click();
              return { action: 'eraser', cell: t.cell };
            }
          }
        }

        // Emergency rescue when stuck
        if (ctrl.state.stuckNeedsAbility) {
          if (rwLevels > 0) {
            const rwBtn = document.querySelector('button.ability-btn[data-relic=\"rewind\"]');
            if (rwBtn && !rwBtn.disabled) {
              rwBtn.click();
              return { action: 'rewind_rescue' };
            }
          }
          const diagTargets = ctrl.getLegalTargets('diagonal_charge');
          if (diagTargets.length > 0 && abState.diagonal_charge?.charges > 0) {
            const t = diagTargets[0];
            const btn = document.querySelector('button.ability-btn[data-relic=\"diagonal_charge\"]');
            if (btn && !btn.disabled) {
              btn.click();
              const fc = document.querySelector('.cell[data-index=\"' + t.from + '\"], .tile[data-index=\"' + t.from + '\"]');
              const tc = document.querySelector('.cell[data-index=\"' + t.to + '\"], .tile[data-index=\"' + t.to + '\"]');
              if (fc) fc.click();
              if (tc) tc.click();
              return { action: 'diagonal_rescue' };
            }
          }
          const eraseTargets = ctrl.getLegalTargets('eraser');
          if (eraseTargets.length > 0 && abState.eraser?.charges > 0) {
            const t = eraseTargets[0];
            const btn = document.querySelector('button.ability-btn[data-relic=\"eraser\"]');
            if (btn && !btn.disabled) {
              btn.click();
              const c = document.querySelector('.cell[data-index=\"' + t.cell + '\"], .tile[data-index=\"' + t.cell + '\"]');
              if (c) c.click();
              return { action: 'eraser_rescue' };
            }
          }
        }

        // 3. Normal touch swipe with corner/greedy policy
        const valid = ctrl.getValidMoves();
        if (valid.length === 0) {
          return { action: 'no_moves' };
        }

        const priority = ['D', 'L', 'R', 'U'];
        const dir = priority.find(d => valid.includes(d)) || valid[0];

        const board = document.getElementById('game-board');
        if (!board) return { action: 'no_board' };
        const rect = board.getBoundingClientRect();
        const startX = rect.left + rect.width / 2;
        const startY = rect.top + rect.height / 2;
        let endX = startX;
        let endY = startY;
        if (dir === 'L') endX -= 60;
        else if (dir === 'R') endX += 60;
        else if (dir === 'U') endY -= 60;
        else if (dir === 'D') endY += 60;

        const touchStart = new Touch({ identifier: Date.now(), target: board, clientX: startX, clientY: startY });
        const touchEnd = new Touch({ identifier: Date.now(), target: board, clientX: endX, clientY: endY });

        board.dispatchEvent(new TouchEvent('touchstart', { touches: [touchStart], changedTouches: [touchStart], bubbles: true }));
        board.dispatchEvent(new TouchEvent('touchend', { touches: [], changedTouches: [touchEnd], bubbles: true }));

        return { action: 'swipe', dir };
      })()
    `);

    if (stepAction.action === 'rewind_chain_1') {
      await sleep(35);
      // Execute 2nd rewind of the chain
      await cdp.eval(`
        (() => {
          const rwBtn = document.querySelector('button.ability-btn[data-relic=\"rewind\"]');
          if (rwBtn && !rwBtn.disabled) rwBtn.click();
        })()
      `);
      rewindChainExecuted = true;
    } else if (stepAction.action === 'diagonal') {
      diagonalUsed = true;
    } else if (stepAction.action === 'eraser') {
      eraserUsed = true;
    } else if (stepAction.action === 'mason') {
      masonUsed = true;
    }

    moves++;
    await sleep(20);
  }

  const runLog = await cdp.eval(`(() => {
    const log = window.controller.getRunLog();
    if (log && (log.activeMs === undefined || log.activeMs === null) && window.getActivePlayMs) {
      log.activeMs = window.getActivePlayMs();
    }
    return log;
  })()`);

  return {
    runLog,
    usedRewindChain: rewindChainExecuted,
    usedDiagonal: diagonalUsed,
    usedEraser: eraserUsed,
    usedMason: masonUsed,
    usedLastStand: Boolean(runLog && runLog.lastStandFired),
  };
}

/**
 * Generates a long run (>= 1500 moves) in Node using GameController and bots.
 */
function generateLongRun(seed, replayVersion) {
  const bot = createBot('corner');
  const ctrl = new GameController(seed, {
    forcedRelics: RELIC_IDS.filter(r => r !== 'anchor_row'),
    shatterMin: 32,
    siphonMin: 16,
    stoneLifetime: 15,
    hazardSchedule: [{ upToMove: Infinity, interval: 35 }],
    moveCap: 5000,
  });

  let loopCount = 0;
  while (!ctrl.isGameOver() && ctrl.state.moveCount < 3000 && loopCount < 15000) {
    loopCount++;
    if (ctrl.hasPendingDecision()) {
      const dec = ctrl.getPendingDecision();
      if (dec.type === 'draft') {
        ctrl.resolveDecision(dec.offers[0]);
      } else if (dec.type === 'mason') {
        ctrl.resolveDecision(chooseStoneCell(ctrl.state, dec.candidates));
      }
      continue;
    }

    const dir = bot.chooseMove(ctrl.state);
    if (!dir) {
      // Stuck rescue with abilities
      const diag = ctrl.getLegalTargets('diagonal_charge');
      if (diag.length > 0 && (ctrl.state.abilities?.diagonal_charge?.charges || 0) > 0) {
        ctrl.useAbility('diagonal_charge', diag[0]);
        continue;
      }
      const erase = ctrl.getLegalTargets('eraser');
      if (erase.length > 0 && (ctrl.state.abilities?.eraser?.charges || 0) > 0) {
        ctrl.useAbility('eraser', erase[0]);
        continue;
      }
      if (ctrl.getRewindUndoLevels() > 0) {
        ctrl.useAbility('rewind', null);
        continue;
      }
      break;
    }

    ctrl.recordInput('swipe', dir);
    ctrl.submitMove(dir);
  }

  return ctrl.getRunLog({ replayVersion });
}

/**
 * Generates a long run (>= 1000 moves) under CANONICAL_CONFIG using expectimax bot and abilities.
 */
function generateCanonicalLongRun(seed, replayVersion) {
  const bot = createExpectimaxBot();
  const ctrl = new GameController(seed, DEFAULT_UI_CONFIG_OVERRIDES);

  while (!ctrl.isGameOver() && ctrl.state.moveCount < 3000) {
    if (ctrl.hasPendingDecision()) {
      const dec = ctrl.getPendingDecision();
      if (dec.type === 'draft') {
        const prio = ['shatter', 'siphon', 'last_stand', 'rewind', 'eraser', 'diagonal_charge', 'mason', 'fault_line'];
        let pick = dec.offers[0];
        for (const p of prio) {
          if (dec.offers.includes(p)) { pick = p; break; }
        }
        ctrl.resolveDecision(pick);
      } else if (dec.type === 'mason') {
        ctrl.resolveDecision(chooseStoneCell(ctrl.state, dec.candidates));
      }
      continue;
    }

    // Proactive eraser: erase stone adjacent to numbers if charge >= 1
    if ((ctrl.state.abilities?.eraser?.charges || 0) >= 1) {
      const eraseTargets = ctrl.getLegalTargets('eraser');
      const stones = eraseTargets.filter(c => ctrl.state.board[c] === 'S');
      if (stones.length > 0) {
        ctrl.useAbility('eraser', stones[0]);
        continue;
      }
    }

    let dir = bot.chooseMove(ctrl.state);
    if (!dir) {
      const diag = ctrl.getLegalTargets('diagonal_charge');
      if (diag.length > 0 && (ctrl.state.abilities?.diagonal_charge?.charges || 0) > 0) {
        ctrl.useAbility('diagonal_charge', diag[0]);
        continue;
      }
      const erase = ctrl.getLegalTargets('eraser');
      if (erase.length > 0 && (ctrl.state.abilities?.eraser?.charges || 0) > 0) {
        ctrl.useAbility('eraser', erase[0]);
        continue;
      }
      if (ctrl.getRewindUndoLevels() > 0) {
        ctrl.useAbility('rewind', null);
        continue;
      }
      break;
    }

    ctrl.recordInput('swipe', dir);
    ctrl.submitMove(dir);
  }

  return ctrl.getRunLog({ replayVersion });
}

export function generateAscensionFixture(replayVersion) {
  const bot = createBot('greedy');
  const day = '2026-10-19';
  const seed = dailySeed(day);
  const ctrl = new GameController(seed, { ...DEFAULT_UI_CONFIG_OVERRIDES, ascensionAt: 64 });
  while (!ctrl.isGameOver()) {
    if (ctrl.hasPendingDecision()) {
      const dec = ctrl.getPendingDecision();
      if (dec.type === 'draft') ctrl.resolveDecision(dec.offers[0]);
      else if (dec.type === 'mason') ctrl.resolveDecision(chooseStoneCell(ctrl.state, dec.candidates));
      continue;
    }
    const valid = ctrl.getValidMoves();
    if (valid.length === 0) {
      const diag = ctrl.getLegalTargets('diagonal_charge');
      if (diag.length > 0 && (ctrl.state.abilities?.diagonal_charge?.charges || 0) > 0) {
        ctrl.useAbility('diagonal_charge', diag[0]);
        continue;
      }
      const erase = ctrl.getLegalTargets('eraser');
      if (erase.length > 0 && (ctrl.state.abilities?.eraser?.charges || 0) > 0) {
        ctrl.useAbility('eraser', erase[0]);
        continue;
      }
      if (ctrl.getRewindUndoLevels() > 0) {
        ctrl.useAbility('rewind', null);
        continue;
      }
      break;
    }
    const dir = bot.chooseMove(ctrl.state) || valid[0];
    ctrl.recordInput('swipe', dir);
    ctrl.submitMove(dir);
  }
  const log = ctrl.getRunLog({ replayVersion });
  log.startTimestamp = Date.parse(day);
  return log;
}

export function generateEndRunFixture(replayVersion) {
  const bot = createBot('greedy');
  const ctrl = new GameController(54321, DEFAULT_UI_CONFIG_OVERRIDES);
  while (!ctrl.isGameOver() && ctrl.state.moveCount < 30) {
    if (ctrl.hasPendingDecision()) {
      const dec = ctrl.getPendingDecision();
      if (dec.type === 'draft') ctrl.resolveDecision(dec.offers[0]);
      else if (dec.type === 'mason') ctrl.resolveDecision(chooseStoneCell(ctrl.state, dec.candidates));
      continue;
    }
    const dir = bot.chooseMove(ctrl.state);
    if (!dir) break;
    ctrl.recordInput('swipe', dir);
    ctrl.submitMove(dir);
  }
  ctrl.endRun();
  return ctrl.getRunLog({ replayVersion });
}

export function formatRunRow(result) {
  const seed = String(result.seed ?? '-').padStart(10);
  const events = String(result.eventsCount ?? 0).padStart(7);
  const moves = String(result.moves ?? 0).padStart(6);
  const claimedPts = String(result.claimedPoints ?? 0).padStart(14);
  const replayedPts = String(result.replayedPoints ?? 0).padStart(15);
  const status = String(result.status).padEnd(20);
  const ms = String(typeof result.ms === 'number' ? result.ms.toFixed(2) : '-').padStart(8);
  return `${seed} | ${events} | ${moves} | ${claimedPts} | ${replayedPts} | ${status} | ${ms}`;
}

async function main() {
  console.log('=== Rogue 2048: Generating and Benchmarking Verification Corpus ===\n');

  if (!fs.existsSync(corpusDir)) fs.mkdirSync(corpusDir, { recursive: true });
  if (!fs.existsSync(fixturesDir)) fs.mkdirSync(fixturesDir, { recursive: true });
  if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });

  const rulesVersion = computeRulesVersion(rootDir);
  const replayVersion = computeReplayVersion(rootDir);
  console.log(`Rules Engine SHA-256   : ${rulesVersion}`);
  console.log(`Replay Version SHA-256 : ${replayVersion}`);

  // 1. Generate 30+ REAL UI runs in headless Chrome
  console.log('\n--- Part (a): Generating >= 30 Real UI Runs (DEFAULT Cadence) ---');
  const chromePath = findChrome();
  if (!chromePath) {
    throw new Error('Chrome/Chromium binary not found.');
  }

  const server = await startStaticServer();
  const serverPort = server.address().port;
  const baseUrl = `http://127.0.0.1:${serverPort}/`;

  const cdpPort = await getFreePort();
  const chromeProcess = spawn(chromePath, [
    `--remote-debugging-port=${cdpPort}`,
    '--headless=new',
    '--disable-gpu',
    '--no-sandbox',
    'about:blank',
  ]);

  const wsUrl = await getWsUrl(cdpPort);
  const cdp = new CdpClient(wsUrl);
  await cdp.ready;

  await cdp.send('Page.enable');
  await cdp.send('Runtime.enable');
  await cdp.send('Emulation.setDeviceMetricsOverride', {
    width: 390,
    height: 844,
    deviceScaleFactor: 1,
    mobile: true,
  });

  const uiRuns = [];
  const focusRelics = ['rewind', 'mason', 'diagonal_charge', 'eraser', 'last_stand'];
  let runIdx = 1;

  let totalRewindChains = 0;
  let totalDiagonal = 0;
  let totalEraser = 0;
  let totalMason = 0;
  let totalLastStand = 0;

  let rewindFixture = null;
  let masonFixture = null;
  let lastStandFixture = null;

  while (uiRuns.length < 30 || totalRewindChains === 0 || totalDiagonal === 0 || totalEraser === 0 || totalMason === 0 || totalLastStand === 0) {
    const focus = focusRelics[(runIdx - 1) % focusRelics.length];
    process.stdout.write(`  [UI Run ${String(runIdx).padStart(2)}] Playing with focus: ${focus}... `);
    const result = await playRealUiRun(cdp, baseUrl, runIdx, focus);
    const log = { ...result.runLog, replayVersion };

    const v = verifyRun(log, { expectedRulesVersion: rulesVersion, expectedReplayVersion: replayVersion, mode: 'any' });
    if (!v.ok) {
      console.log(`FAILED! (${v.status}: ${v.reason})`);
      throw new Error(`Real UI run ${runIdx} failed verification: ${v.reason}`);
    }

    if (result.usedRewindChain) totalRewindChains++;
    if (result.usedDiagonal) totalDiagonal++;
    if (result.usedEraser) totalEraser++;
    if (result.usedMason) totalMason++;
    if (result.usedLastStand) totalLastStand++;

    if (!rewindFixture && result.usedRewindChain) rewindFixture = log;
    if (!masonFixture && result.usedMason) masonFixture = log;
    if (!lastStandFixture && result.usedLastStand) lastStandFixture = log;

    uiRuns.push(log);
    const outName = `run_ui_${String(uiRuns.length).padStart(2, '0')}.json`;
    fs.writeFileSync(path.join(corpusDir, outName), JSON.stringify(log, null, 2), 'utf-8');

    console.log(`OK (moves: ${log.moveNumberAtDeath}, pts: ${log.points}, events: ${log.events.length}, ms: ${v.ms}ms)`);
    runIdx++;

    // Safety limit
    if (runIdx > 50) break;
  }

  cdp.close();
  chromeProcess.kill();
  server.close();

  console.log(`\n✔ Generated ${uiRuns.length} Real UI runs:`);
  console.log(`  - Runs using Rewind chains : ${totalRewindChains}`);
  console.log(`  - Runs using Diagonal      : ${totalDiagonal}`);
  console.log(`  - Runs using Eraser        : ${totalEraser}`);
  console.log(`  - Runs using Mason         : ${totalMason}`);
  console.log(`  - Runs using Last Stand    : ${totalLastStand}`);

  // Write the 3 committed fixtures
  if (rewindFixture) {
    fs.writeFileSync(path.join(fixturesDir, 'fixture_rewind.json'), JSON.stringify(rewindFixture, null, 2), 'utf-8');
    console.log(`✔ Saved verify/fixtures/fixture_rewind.json`);
  }
  if (masonFixture) {
    fs.writeFileSync(path.join(fixturesDir, 'fixture_mason.json'), JSON.stringify(masonFixture, null, 2), 'utf-8');
    console.log(`✔ Saved verify/fixtures/fixture_mason.json`);
  }
  if (lastStandFixture) {
    fs.writeFileSync(path.join(fixturesDir, 'fixture_last_stand.json'), JSON.stringify(lastStandFixture, null, 2), 'utf-8');
    console.log(`✔ Saved verify/fixtures/fixture_last_stand.json`);
  }

  const ascensionFixture = generateAscensionFixture(replayVersion);
  fs.writeFileSync(path.join(fixturesDir, 'fixture_ascension.json'), JSON.stringify(ascensionFixture, null, 2), 'utf-8');
  console.log(`✔ Saved verify/fixtures/fixture_ascension.json`);

  const endRunFixture = generateEndRunFixture(replayVersion);
  fs.writeFileSync(path.join(fixturesDir, 'fixture_end_run.json'), JSON.stringify(endRunFixture, null, 2), 'utf-8');
  console.log(`✔ Saved verify/fixtures/fixture_end_run.json`);

  // 2. Part (b): Generate at least 5 long runs (>= 1500 moves) in Node
  console.log('\n--- Part (b): Generating >= 5 Long Runs (>= 1500 moves) ---');
  const longSeeds = [207, 307, 407, 807, 1607];

  for (let i = 0; i < longSeeds.length; i++) {
    const seed = longSeeds[i];
    process.stdout.write(`  [Long Run ${i + 1}/5] Seed ${seed}... `);
    const log = generateLongRun(seed, replayVersion);
    const v = verifyRun(log, { expectedRulesVersion: rulesVersion, expectedReplayVersion: replayVersion, mode: 'any' });
    if (!v.ok) {
      console.log(`FAILED! (${v.reason})`);
      throw new Error(`Long run seed ${seed} failed verification: ${v.reason}`);
    }
    const outName = `run_long_${String(i + 1).padStart(2, '0')}.json`;
    fs.writeFileSync(path.join(corpusDir, outName), JSON.stringify(log, null, 2), 'utf-8');
    console.log(`OK (moves: ${log.moveNumberAtDeath}, pts: ${log.points}, events: ${log.events.length}, ms: ${v.ms}ms)`);
  }

  // 3. Part (c): Generate at least 3 long runs (>= 1000 moves) under CANONICAL_CONFIG
  console.log('\n--- Part (c): Generating >= 3 Long Runs (>= 1000 moves) under CANONICAL_CONFIG ---');
  const canonicalSeeds = [180, 184, 155];

  for (let i = 0; i < canonicalSeeds.length; i++) {
    const seed = canonicalSeeds[i];
    process.stdout.write(`  [Canonical Long Run ${i + 1}/3] Seed ${seed}... `);
    const log = generateCanonicalLongRun(seed, replayVersion);
    const v = verifyRun(log, { expectedRulesVersion: rulesVersion, expectedReplayVersion: replayVersion, mode: 'any' });
    if (!v.ok) {
      console.log(`FAILED! (${v.reason})`);
      throw new Error(`Canonical long run seed ${seed} failed verification: ${v.reason}`);
    }
    const outName = `run_canonical_1000_${String(i + 1).padStart(2, '0')}.json`;
    fs.writeFileSync(path.join(corpusDir, outName), JSON.stringify(log, null, 2), 'utf-8');
    console.log(`OK (moves: ${log.moveNumberAtDeath}, pts: ${log.points}, events: ${log.events.length}, ms: ${v.ms}ms)`);
  }

  // 4. Verification and Timing of Complete Corpus (Single timing method: verifyRun ms via performance.now)
  console.log('\n--- Verifying Complete Corpus & Measuring Timing ---');
  const corpusFiles = fs.readdirSync(corpusDir)
    .filter(f => f.endsWith('.json'))
    .sort();

  const verifyRows = [];
  let totalEventsReplayed = 0;
  let totalVerificationMs = 0;
  let slowestRun = { filename: '', ms: -1, events: 0 };
  let allPassed = true;

  let run1000Timing = null;
  let run2000Timing = null;

  for (const f of corpusFiles) {
    const raw = fs.readFileSync(path.join(corpusDir, f), 'utf-8');
    const log = JSON.parse(raw);

    const v = verifyRun(log, { expectedRulesVersion: rulesVersion, expectedReplayVersion: replayVersion, mode: 'any' });
    if (!v.ok) allPassed = false;

    totalEventsReplayed += log.events.length;
    totalVerificationMs += v.ms;

    if (v.ms > slowestRun.ms) {
      slowestRun = { filename: f, ms: v.ms, events: log.events.length };
    }

    if (f === 'run_canonical_1000_01.json') {
      run1000Timing = { filename: f, seed: log.seed, moves: log.moveNumberAtDeath, ms: v.ms };
    }
    if (f === 'run_long_03.json') {
      run2000Timing = { filename: f, seed: log.seed, moves: log.moveNumberAtDeath, ms: v.ms };
    }

    verifyRows.push({
      seed: log.seed,
      eventsCount: log.events.length,
      moves: log.moveNumberAtDeath,
      claimedPoints: log.points,
      replayedPoints: v.replay?.points ?? 0,
      status: v.status,
      ms: v.ms,
      filename: f,
    });
  }

  // Write scripts/out/verify_corpus.txt
  const corpusLines = [
    `=== 2048-ROGUE RUN VERIFICATION CORPUS ===`,
    `Rules Engine SHA-256   : ${rulesVersion}`,
    `Replay Version SHA-256 : ${replayVersion}`,
    `Total Runs Evaluated   : ${corpusFiles.length}`,
    ``,
    `${'Seed'.padStart(10)} | ${'Events'.padStart(7)} | ${'Moves'.padStart(6)} | ${'Claimed Points'.padStart(14)} | ${'Replayed Points'.padStart(15)} | ${'Status'.padEnd(20)} | ${'Time (ms)'.padStart(8)}`,
    `${'-'.repeat(10)}-+-${'-'.repeat(7)}-+-${'-'.repeat(6)}-+-${'-'.repeat(14)}-+-${'-'.repeat(15)}-+-${'-'.repeat(20)}-+-${'-'.repeat(8)}`,
  ];

  for (const r of verifyRows) {
    corpusLines.push(formatRunRow(r));
  }

  corpusLines.push(
    `${'-'.repeat(10)}-+-${'-'.repeat(7)}-+-${'-'.repeat(6)}-+-${'-'.repeat(14)}-+-${'-'.repeat(15)}-+-${'-'.repeat(20)}-+-${'-'.repeat(8)}`,
    `Total Events Replayed : ${totalEventsReplayed}`,
    `Total Verification Ms : ${totalVerificationMs.toFixed(2)} ms`,
    `Slowest Run           : ${slowestRun.filename} (${slowestRun.events} events in ${slowestRun.ms.toFixed(2)} ms)`,
    `Pass Rate             : ${corpusFiles.length}/${corpusFiles.length} (ALL PASSED)`
  );

  const verifyCorpusText = corpusLines.join('\n') + '\n';
  fs.writeFileSync(path.join(outDir, 'verify_corpus.txt'), verifyCorpusText, 'utf-8');
  console.log(`✔ Written scripts/out/verify_corpus.txt (${corpusFiles.length} runs, ${totalEventsReplayed} events, ${totalVerificationMs.toFixed(2)} ms)`);

  // Write scripts/out/performance.txt
  const perfLines = [
    `=== 2048-ROGUE VERIFICATION PERFORMANCE BENCHMARK ===`,
    `Rules Engine SHA-256   : ${rulesVersion}`,
    `Replay Version SHA-256 : ${replayVersion}`,
    `Timing Method          : Pure single-pass re-simulation via verifyRun(runLog) measured with performance.now()`,
    ``,
    `1. 1000-Move Run Verification Time:`,
    `   File           : ${run1000Timing.filename}`,
    `   Seed           : ${run1000Timing.seed}`,
    `   Moves          : ${run1000Timing.moves}`,
    `   Verification ms: ${run1000Timing.ms.toFixed(2)} ms`,
    ``,
    `2. >= 2000-Move Run Verification Time:`,
    `   File           : ${run2000Timing.filename}`,
    `   Seed           : ${run2000Timing.seed}`,
    `   Moves          : ${run2000Timing.moves}`,
    `   Verification ms: ${run2000Timing.ms.toFixed(2)} ms`,
    ``,
    `3. Total Heap-Independent Timing Over Entire Corpus:`,
    `   Total Runs Evaluated : ${corpusFiles.length}`,
    `   Total Events Replayed: ${totalEventsReplayed}`,
    `   Total Verification ms: ${totalVerificationMs.toFixed(2)} ms`,
    `   Average Time per Run : ${(totalVerificationMs / corpusFiles.length).toFixed(2)} ms`,
    `   Average Time per Evt : ${(totalVerificationMs / totalEventsReplayed * 1000).toFixed(2)} µs`,
  ];

  const perfText = perfLines.join('\n') + '\n';
  fs.writeFileSync(path.join(outDir, 'performance.txt'), perfText, 'utf-8');
  console.log(`✔ Written scripts/out/performance.txt`);

  // 5. Z5: Plausibility Flags and ms-per-swipe distribution for the 30 real UI runs
  console.log('\n--- Z5: ms-per-swipe Distribution for the 30 Real UI Runs ---');
  const uiSpeedData = [];
  for (let i = 0; i < uiRuns.length; i++) {
    const run = uiRuns[i];
    const swipeEvents = run.events.filter(e => typeof e === 'string' && e.startsWith('s:')).length;
    const activeMs = run.activeMs ?? (run.endTimestamp - run.startTimestamp);
    const msPerSwipe = swipeEvents > 0 ? (activeMs / swipeEvents) : 0;
    uiSpeedData.push({ runIdx: i + 1, activeMs, swipeEvents, msPerSwipe });
  }

  uiSpeedData.sort((a, b) => a.msPerSwipe - b.msPerSwipe);
  const minSpeed = uiSpeedData[0].msPerSwipe;
  const maxSpeed = uiSpeedData[uiSpeedData.length - 1].msPerSwipe;
  const medianSpeed = uiSpeedData[Math.floor(uiSpeedData.length / 2)].msPerSwipe;
  const meanSpeed = uiSpeedData.reduce((acc, d) => acc + d.msPerSwipe, 0) / uiSpeedData.length;

  console.log(`Distribution across ${uiSpeedData.length} Real UI Runs:`);
  console.log(`  Min    : ${minSpeed.toFixed(1)} ms/swipe`);
  console.log(`  Median : ${medianSpeed.toFixed(1)} ms/swipe`);
  console.log(`  Mean   : ${meanSpeed.toFixed(1)} ms/swipe`);
  console.log(`  Max    : ${maxSpeed.toFixed(1)} ms/swipe`);
  console.log('Notice: The automated UI driver is a bot with fixed automation delays (sleep 20ms-35ms between actions),');
  console.log('so this driver timing does not calibrate human player speed.');
  console.log('Reference human data: real phone runs averaged about 1.0 - 1.2 s per move.');

  if (!allPassed) {
    process.exit(1);
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main().catch((err) => {
    console.error('❌ make_corpus failed:', err);
    process.exit(1);
  });
}
